const X = size_x, Z = size_z, T = tile_size, g = Math.min(gap, T * 0.4), t = thickness, bed = 0.01, s = seed;
const nz = Math.ceil(Z / T) + 1, nx = Math.ceil(X / T) + 2;
const z0 = addpoint(0, [0, 0, 0]); setpointgroup(0, 'dark', z0, 0); removepoint(0, z0);
for (let j = 0; j < nz; j++) {
  const off = pattern === 'offset' && j % 2 ? T / 2 : 0;
  for (let i = -1; i < nx; i++) {
    const xa = -X / 2 + i * T - off + g / 2, xb = xa + T - g, za = -Z / 2 + j * T + g / 2, zb = za + T - g;
    const x0 = Math.max(-X / 2, xa), x1 = Math.min(X / 2, xb), zz0 = Math.max(-Z / 2, za), zz1 = Math.min(Z / 2, zb);
    if (x1 - x0 < 0.004 || zz1 - zz0 < 0.004) continue;
    const h = t + (rand(i, j, s) - 0.5) * 2 * height_jitter;
    const q = addpoint(0, [(x0 + x1) / 2, bed + h / 2, (zz0 + zz1) / 2]);
    setpointattrib(0, 'scale', q, [x1 - x0, h, zz1 - zz0]);
    setpointattrib(0, 'tint', q, 0.9 + 0.18 * rand(i, j, s, 2));
    if (pattern === 'checker' && (i + j) % 2 !== 0) setpointgroup(0, 'dark', q, 1);
  }
}
